"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useState } from "react";

import { Kbd } from "@/components/ui/kbd";

import { BlockFrame } from "../parts/block-frame";
import { CoverArt } from "./media-player/cover-art";
import { TRACKS, formatClock } from "./media-player/data";
import { SeekBar } from "./media-player/seek-bar";
import { TrackRow } from "./media-player/track-row";
import { Transport } from "./media-player/transport";
import { usePlayer } from "./media-player/use-player";
import { VolumeControl } from "./media-player/volume-control";

const SHORTCUTS: { keys: string[]; label: string }[] = [
  { keys: ["Space"], label: "Play or pause" },
  { keys: ["J", "L"], label: "Back or ahead 10 s" },
  { keys: ["P", "N"], label: "Previous or next" },
];

const TOTAL = TRACKS.reduce((sum, track) => sum + track.duration, 0);

/**
 * A player for Fernhill radio, the calm sound clinics play in their waiting
 * rooms. It plays a simulated timeline with drawn covers: play, pause, seek,
 * skip, set the volume and pick a track. Keys work anywhere inside the card.
 */
export function MediaPlayer({ className }: { className?: string }) {
  const player = usePlayer();
  const [volume, setVolume] = useState(70);
  const [muted, setMuted] = useState(false);
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const railId = useId();
  const { track, playing, position } = player;

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.metaKey || event.ctrlKey || event.altKey) return;
    const target = event.target;
    const onRange =
      target instanceof HTMLInputElement && target.type === "range";
    const onButton = target instanceof HTMLButtonElement;
    const key = event.key.toLowerCase();
    if ((key === " " && !onButton) || key === "k") player.toggle();
    else if (key === "j" || (key === "arrowleft" && !onRange))
      player.seek(position - 10);
    else if (key === "l" || (key === "arrowright" && !onRange))
      player.seek(position + 10);
    else if (key === "n") player.next();
    else if (key === "p") player.previous();
    else return;
    event.preventDefault();
  };

  return (
    <BlockFrame
      aria-labelledby={titleId}
      className={className}
      onKeyDown={onKeyDown}
    >
      <header className="flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Fernhill radio
        </h2>
        <p className="text-sm text-muted-foreground">
          Calm sound for the waiting room
        </p>
      </header>

      <div className="grid @2xl:grid-cols-[19rem_1fr]">
        <div className="flex min-w-0 flex-col gap-4 p-5">
          <CoverArt
            track={track}
            className="mx-auto w-full max-w-60 @2xl:max-w-none"
          />
          <div className="relative h-11 overflow-hidden">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.div
                key={track.id}
                className="flex flex-col"
                initial={
                  reduceMotion ? { opacity: 0 } : { opacity: 0, y: "0.75rem" }
                }
                animate={{ opacity: 1, y: 0 }}
                exit={
                  reduceMotion
                    ? { opacity: 0, transition: { duration: 0 } }
                    : { opacity: 0, y: "-0.5rem" }
                }
                transition={{
                  duration: reduceMotion ? 0 : 0.25,
                  ease: "easeOut",
                }}
              >
                <h3 className="truncate text-base font-semibold">
                  {track.title}
                </h3>
                <p className="truncate text-sm text-muted-foreground">
                  {track.source}
                </p>
              </motion.div>
            </AnimatePresence>
          </div>
          <p role="status" className="sr-only">
            {playing ? `Playing ${track.title}` : `Paused, ${track.title}`}
          </p>
          <SeekBar
            position={position}
            duration={track.duration}
            onSeek={player.seek}
          />
          <Transport
            playing={playing}
            onToggle={player.toggle}
            onPrevious={player.previous}
            onNext={player.next}
          />
          <ul
            aria-label="Keyboard shortcuts"
            className="flex flex-wrap justify-center gap-x-4 gap-y-1.5 text-xs text-muted-foreground"
          >
            {SHORTCUTS.map((shortcut) => (
              <li key={shortcut.label} className="flex items-center gap-1.5">
                <span className="flex gap-0.5">
                  {shortcut.keys.map((key) => (
                    <Kbd key={key}>{key}</Kbd>
                  ))}
                </span>
                {shortcut.label}
              </li>
            ))}
          </ul>
        </div>

        <div className="flex min-w-0 flex-col gap-2 border-t border-border p-3 @2xl:border-t-0 @2xl:border-l">
          <div className="flex flex-wrap items-center justify-between gap-2 px-2 pt-1">
            <div className="min-w-0">
              <h3 className="text-sm font-medium">Playlist</h3>
              <p className="text-xs tabular-nums text-muted-foreground">
                {TRACKS.length} tracks, {formatClock(TOTAL)}
              </p>
            </div>
            <VolumeControl
              volume={volume}
              onVolume={(value) => {
                setVolume(value);
                setMuted(false);
              }}
              muted={muted}
              onMute={() => setMuted(!muted)}
            />
          </div>
          <ol aria-label="Tracks" className="flex flex-col gap-0.5">
            {TRACKS.map((item, index) => (
              <TrackRow
                key={item.id}
                track={item}
                number={index + 1}
                current={index === player.index}
                playing={playing}
                onChoose={() => player.go(index)}
                railId={railId}
              />
            ))}
          </ol>
        </div>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId } from "react";

import { cn } from "@/lib/utils";

import type { Track } from "./data";

const hue = (index: number) => `var(--chart-${index})`;

/** The drawn layer of one cover, drawn in a 100 by 100 box. */
function CoverMotif({ track }: { track: Track }) {
  const [, ink] = track.hues;
  if (track.pattern === "sun") {
    return (
      <>
        <circle cx="64" cy="40" r="20" fill={hue(ink)} />
        <path
          d="M0 72 Q25 60 50 70 T100 66 V100 H0z"
          fill={hue(ink)}
          fillOpacity="0.45"
        />
        <path
          d="M0 84 Q30 74 60 82 T100 80 V100 H0z"
          fill={hue(ink)}
          fillOpacity="0.75"
        />
      </>
    );
  }
  if (track.pattern === "waves") {
    return (
      <>
        {[38, 52, 66, 80].map((y, index) => (
          <path
            key={y}
            d={`M0 ${y} Q12.5 ${y - 8} 25 ${y} T50 ${y} T75 ${y} T100 ${y}`}
            fill="none"
            stroke={hue(ink)}
            strokeWidth={4 - index * 0.6}
            strokeLinecap="round"
            opacity={1 - index * 0.18}
          />
        ))}
        <circle cx="24" cy="22" r="7" fill={hue(ink)} fillOpacity="0.8" />
      </>
    );
  }
  return (
    <>
      {[34, 26, 18, 10].map((r, index) => (
        <circle
          key={r}
          cx="50"
          cy="50"
          r={r}
          fill="none"
          stroke={hue(ink)}
          strokeWidth="3.5"
          opacity={0.4 + index * 0.2}
        />
      ))}
      <circle cx="50" cy="50" r="4" fill={hue(ink)} />
    </>
  );
}

/**
 * A cover drawn for each track: a two-hue gradient sky with a sun, waves or
 * rings on top. A new track's cover fades in over the old one.
 */
export function CoverArt({
  track,
  className,
}: {
  track: Track;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  const gradientId = useId();
  const [sky, ink] = track.hues;
  return (
    <div
      className={cn(
        "relative aspect-square overflow-hidden rounded-xl border border-border bg-muted",
        className,
      )}
    >
      <AnimatePresence initial={false}>
        <motion.svg
          key={track.id}
          aria-hidden="true"
          viewBox="0 0 100 100"
          preserveAspectRatio="xMidYMid slice"
          className="absolute inset-0 size-full"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={
            reduceMotion ? { duration: 0 } : { duration: 0.35, ease: "easeOut" }
          }
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0.4" y2="1">
              <stop offset="0" stopColor={hue(sky)} />
              <stop offset="1" stopColor={hue(ink)} stopOpacity="0.55" />
            </linearGradient>
          </defs>
          <rect width="100" height="100" fill={`url(#${gradientId})`} />
          <CoverMotif track={track} />
        </motion.svg>
      </AnimatePresence>
    </div>
  );
}

/** The way a generated cover is drawn. */
export type CoverPattern = "sun" | "waves" | "rings";

/** One track in the Fernhill radio playlist. */
export interface Track {
  id: string;
  title: string;
  /** Where the track comes from, shown under the title. */
  source: string;
  /** Length in seconds. */
  duration: number;
  pattern: CoverPattern;
  /** Two chart hues, 1 to 5, that colour the cover: the sky and the shape. */
  hues: [number, number];
}

/** The sample playlist: calm waiting room sets and two short staff briefings. */
export const TRACKS: Track[] = [
  {
    id: "harbour",
    title: "Morning light over Harbour Street",
    source: "Waiting room set",
    duration: 222,
    pattern: "sun",
    hues: [1, 3],
  },
  {
    id: "tide",
    title: "Slow tide",
    source: "Waiting room set",
    duration: 258,
    pattern: "waves",
    hues: [2, 1],
  },
  {
    id: "briefing-12",
    title: "Five minutes before opening",
    source: "Staff briefing, episode 12",
    duration: 365,
    pattern: "rings",
    hues: [4, 5],
  },
  {
    id: "rain",
    title: "Breathing with the rain",
    source: "Calm corner",
    duration: 176,
    pattern: "waves",
    hues: [1, 4],
  },
  {
    id: "orchard",
    title: "Orchard Road at dusk",
    source: "Waiting room set",
    duration: 310,
    pattern: "sun",
    hues: [5, 3],
  },
  {
    id: "briefing-13",
    title: "A reminder text that gets a reply",
    source: "Staff briefing, episode 13",
    duration: 444,
    pattern: "rings",
    hues: [2, 3],
  },
];

/** Writes seconds as minutes and seconds, such as 3:07. */
export function formatClock(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

/** Writes seconds for a screen reader, such as "3 minutes 7 seconds". */
export function spokenClock(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(whole / 60);
  const rest = whole % 60;
  return `${minutes} minute${minutes === 1 ? "" : "s"} ${rest} second${rest === 1 ? "" : "s"}`;
}

"use client";

import { useId } from "react";

import { Slider } from "@/components/ui/slider";

import { formatClock, spokenClock } from "./data";

/** Props for the seek bar. */
export interface SeekBarProps {
  /** Seconds played. */
  position: number;
  /** Seconds in the track. */
  duration: number;
  onSeek: (seconds: number) => void;
}

/**
 * A slider over the track with the time played on the left and the
 * length on the right. Arrows step 1 second, Page keys 30.
 */
export function SeekBar({ position, duration, onSeek }: SeekBarProps) {
  const labelId = useId();
  return (
    <div className="flex flex-col gap-1.5">
      <span id={labelId} className="sr-only">
        Seek, {spokenClock(position)} of {spokenClock(duration)}
      </span>
      <Slider
        min={0}
        max={Math.floor(duration)}
        step={1}
        value={[Math.floor(position)]}
        aria-labelledby={labelId}
        onValueChange={([seconds]) => onSeek(seconds ?? 0)}
        onKeyDown={(event) => {
          const jump =
            event.key === "PageUp" ? 30 : event.key === "PageDown" ? -30 : 0;
          if (jump === 0) return;
          event.preventDefault();
          onSeek(Math.min(duration, Math.max(0, position + jump)));
        }}
        className="h-4"
      />
      <span
        aria-hidden="true"
        className="flex justify-between text-xs tabular-nums text-muted-foreground"
      >
        <span>{formatClock(position)}</span>
        <span>{formatClock(duration)}</span>
      </span>
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatClock, spokenClock, type Track } from "./data";
import { PlayingBars } from "./playing-bars";

/** Props for one row of the playlist. */
export interface TrackRowProps {
  track: Track;
  /** The row's place in the list, from 1. */
  number: number;
  current: boolean;
  playing: boolean;
  onChoose: () => void;
  /** Shared by every row, so the rail glides between rows of one list only. */
  railId: string;
}

/**
 * One track in the playlist: its number or the playing bars, its title and
 * source, and its length. The current row carries a rail that glides to the next current row.
 */
export function TrackRow({
  track,
  number,
  current,
  playing,
  onChoose,
  railId,
}: TrackRowProps) {
  const reduceMotion = useReducedMotion();
  return (
    <li className="relative">
      {current ? (
        <motion.span
          layoutId={railId}
          aria-hidden="true"
          transition={
            reduceMotion
              ? { duration: 0 }
              : { type: "spring", stiffness: 300, damping: 32, mass: 1 }
          }
          className="absolute inset-0 rounded-lg bg-muted"
        >
          <span className="absolute inset-y-2 left-0 w-0.5 rounded-full bg-chart-1" />
        </motion.span>
      ) : null}
      <Button
        variant="ghost"
        onClick={onChoose}
        aria-current={current ? "true" : undefined}
        aria-label={`${track.title}, ${track.source}, ${spokenClock(track.duration)}${current ? (playing ? ", playing" : ", paused") : ""}`}
        className="relative h-auto w-full justify-start text-left"
      >
        <span className="grid w-full grid-cols-[1.5rem_1fr_auto] items-center gap-3 py-1 font-normal">
        <span className="flex justify-center text-xs tabular-nums text-muted-foreground">
          {current ? <PlayingBars playing={playing} /> : number}
        </span>
        <span className="flex min-w-0 flex-col">
          <span
            className={cn(
              "truncate text-sm",
              current ? "font-medium text-foreground" : "text-foreground",
            )}
          >
            {track.title}
          </span>
          <span className="truncate text-xs text-muted-foreground">
            {track.source}
          </span>
        </span>
        <span className="text-xs tabular-nums text-muted-foreground">
          {formatClock(track.duration)}
        </span>
        </span>
      </Button>
    </li>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

const HEIGHTS = [
  [0.35, 1, 0.5, 0.8, 0.35],
  [0.9, 0.4, 1, 0.3, 0.9],
  [0.55, 0.85, 0.3, 1, 0.55],
];

/**
 * Three small bars beside the current track. They pulse while it plays and
 * rest at a low height when paused or when motion is reduced.
 */
export function PlayingBars({
  playing,
  className,
}: {
  playing: boolean;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  const moving = playing && !reduceMotion;
  return (
    <span
      aria-hidden="true"
      className={cn("flex h-3.5 w-3.5 items-end justify-between", className)}
    >
      {HEIGHTS.map((steps, index) => (
        <motion.span
          key={index}
          className="h-full w-1 origin-bottom rounded-full bg-chart-1"
          initial={false}
          animate={{ scaleY: moving ? steps : playing ? 0.7 : 0.3 }}
          transition={
            moving
              ? {
                  duration: 1.1 + index * 0.15,
                  repeat: Infinity,
                  ease: "easeInOut",
                }
              : { duration: 0.2 }
          }
        />
      ))}
    </span>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import {
  PlayerPauseFilledIcon,
  PlayerPlayFilledIcon,
} from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { NextIcon, PreviousIcon } from "./icons";

/** Props for the previous, play and next buttons. */
export interface TransportProps {
  playing: boolean;
  onToggle: () => void;
  onPrevious: () => void;
  onNext: () => void;
}

/** Previous, play or pause, and next. The play mark swaps for pause with a short scale. */
export function Transport({
  playing,
  onToggle,
  onPrevious,
  onNext,
}: TransportProps) {
  const reduceMotion = useReducedMotion();
  return (
    <div className="flex items-center justify-center gap-3">
      <Button
        variant="ghost"
        size="icon"
        aria-label="Previous track"
        onClick={onPrevious}
      >
        <PreviousIcon aria-hidden="true" />
      </Button>
      <Button
        size="icon"
        aria-label={playing ? "Pause" : "Play"}
        onClick={onToggle}
        className="size-12"
      >
        <AnimatePresence mode="wait" initial={false}>
          <motion.span
            key={playing ? "pause" : "play"}
            className="flex"
            initial={reduceMotion ? false : { scale: 0.5, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={
              reduceMotion
                ? { opacity: 0, transition: { duration: 0 } }
                : { scale: 0.5, opacity: 0 }
            }
            transition={{ duration: 0.12, ease: "easeOut" }}
          >
            {playing ? (
              <PlayerPauseFilledIcon aria-hidden="true" className="size-5" />
            ) : (
              <PlayerPlayFilledIcon aria-hidden="true" className="size-5" />
            )}
          </motion.span>
        </AnimatePresence>
      </Button>
      <Button
        variant="ghost"
        size="icon"
        aria-label="Next track"
        onClick={onNext}
      >
        <NextIcon aria-hidden="true" />
      </Button>
    </div>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
