"use client";

import { useCallback, useEffect, useReducer } from "react";

import { TRACKS } from "./data";

interface PlayerState {
  index: number;
  /** Seconds played in the current track. */
  position: number;
  playing: boolean;
}

type PlayerAction =
  | { type: "toggle" }
  | { type: "tick"; seconds: number }
  | { type: "seek"; seconds: number }
  | { type: "go"; index: number }
  | { type: "step"; by: 1 | -1 };

const wrap = (index: number) => (index + TRACKS.length) % TRACKS.length;
const lengthOf = (index: number) => TRACKS[index]?.duration ?? 0;

function reduce(state: PlayerState, action: PlayerAction): PlayerState {
  switch (action.type) {
    case "toggle":
      return { ...state, playing: !state.playing };
    case "tick": {
      const position = state.position + action.seconds;
      if (position < lengthOf(state.index)) return { ...state, position };
      // The last track ends the list; any other moves on to the next.
      const last = state.index === TRACKS.length - 1;
      return { index: last ? 0 : state.index + 1, position: 0, playing: !last };
    }
    case "seek":
      return {
        ...state,
        position: Math.min(lengthOf(state.index), Math.max(0, action.seconds)),
      };
    case "go":
      return state.index === action.index
        ? { ...state, playing: !state.playing }
        : { index: action.index, position: 0, playing: true };
    case "step":
      // Previous restarts a track that has played past 3 seconds, as most players do.
      if (action.by === -1 && state.position > 3)
        return { ...state, position: 0 };
      return { ...state, index: wrap(state.index + action.by), position: 0 };
  }
}

const TICK_MS = 250;

/**
 * The simulated timeline behind the player. A timer advances the position
 * while playing and is cleared on pause and unmount. No audio file is loaded.
 */
export function usePlayer() {
  const [state, dispatch] = useReducer(reduce, {
    index: 0,
    position: 48,
    playing: false,
  });

  useEffect(() => {
    if (!state.playing) return;
    const timer = window.setInterval(
      () => dispatch({ type: "tick", seconds: TICK_MS / 1000 }),
      TICK_MS,
    );
    return () => window.clearInterval(timer);
  }, [state.playing]);

  return {
    ...state,
    track: TRACKS[state.index] ?? TRACKS[0]!,
    toggle: useCallback(() => dispatch({ type: "toggle" }), []),
    seek: useCallback(
      (seconds: number) => dispatch({ type: "seek", seconds }),
      [],
    ),
    go: useCallback((index: number) => dispatch({ type: "go", index }), []),
    next: useCallback(() => dispatch({ type: "step", by: 1 }), []),
    previous: useCallback(() => dispatch({ type: "step", by: -1 }), []),
  };
}

"use client";

import { useId } from "react";

import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";

import { VolumeIcon, VolumeOffIcon } from "./icons";

/** Props for the volume control. */
export interface VolumeControlProps {
  /** From 0 to 100. */
  volume: number;
  onVolume: (volume: number) => void;
  muted: boolean;
  onMute: () => void;
}

/** A mute button and a volume slider. Arrows step the volume by 5. */
export function VolumeControl({
  volume,
  onVolume,
  muted,
  onMute,
}: VolumeControlProps) {
  const labelId = useId();
  const level = muted ? 0 : volume;
  return (
    <div className="flex items-center gap-1">
      <Button
        variant="ghost"
        size="icon"
        aria-pressed={muted}
        aria-label={muted ? "Unmute" : "Mute"}
        onClick={onMute}
      >
        {muted || volume === 0 ? (
          <VolumeOffIcon aria-hidden="true" />
        ) : (
          <VolumeIcon aria-hidden="true" />
        )}
      </Button>
      <span id={labelId} className="sr-only">
        Volume, {level}%
      </span>
      <Slider
        min={0}
        max={100}
        step={5}
        value={[level]}
        aria-labelledby={labelId}
        onValueChange={([next]) => onVolume(next ?? 0)}
        className="h-4 w-24"
      />
    </div>
  );
}
